commands.command:
/usr/bin/bash -lc "node <<'NODE'
const fs = require('fs');
const assert = require('assert');
const source = fs.readFileSync('src/editors/PersonnelEditor.vue', 'utf8');
const script = source.match(/<script>([\\s\\S]*?)<\\/script>/)[1];
assert(script.includes('import personnelConfig from \"../config/personnel-form.json\"'));
assert("'!script.includes('"'getStaticConfig'));
const config = JSON.parse(fs.readFileSync('src/config/personnel-form.json', 'utf8'));
assert.deepStrictEqual(config.rule.map(x => x.field), ['parentId','parentCode','parentName','unitLookup']);
new Function(script.replace(/"'^import .*;$/gm, '"'').replace('export default', 'return'));
const structure = fs.readFileSync('src/editors/StructureEditor.vue', 'utf8');
assert(structure.includes('getStaticConfig(\"structure-form\")'));
console.log('Personnel script syntax and local config checked; Structure remote loader unchanged.');
NODE"

